#!/usr/bin/env python3
"""Block brute-force sources found in Wazuh alerts. Dry-run unless --apply."""
import ipaddress, json, subprocess, sys, logging

ALERTS = "/var/ossec/logs/alerts/alerts.json"
ALLOW = [ipaddress.ip_network(n) for n in ("10.10.0.0/16", "192.0.2.0/24")]
RULES = {"5712"}          # sshd brute force (built-in correlation)
MAX_BLOCKS = 20           # circuit breaker per run
APPLY = "--apply" in sys.argv
logging.basicConfig(filename="/var/log/auto-block.log", level=logging.INFO,
                    format="%(asctime)s %(message)s")

def sources():
    seen = set()
    for line in open(ALERTS):
        try:
            a = json.loads(line)
            ip = ipaddress.ip_address(a["data"]["srcip"])
        except (ValueError, KeyError):
            continue
        if a["rule"]["id"] in RULES and not any(ip in n for n in ALLOW):
            seen.add(str(ip))
    return sorted(seen)

todo = sources()
if len(todo) > MAX_BLOCKS:
    logging.error("refusing %d blocks (limit %d)", len(todo), MAX_BLOCKS)
    sys.exit(2)
for ip in todo:
    cmd = ["nft", "add", "element", "inet", "filter", "blocklist",
           "{ " + ip + " timeout 1h }"]
    logging.info("%s %s", "BLOCK" if APPLY else "DRY-RUN", ip)
    if APPLY:
        subprocess.run(cmd, check=True)

